window.kbPageData["views/entry/k-6d966e1bff9e9de9"] = {"key":"entry/k-6d966e1bff9e9de9","state":{"route":"entry/k-6d966e1bff9e9de9"},"node":{"id":"k-6d966e1bff9e9de9","mode":"k","title":"两点之间线段最短","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2024 行政执法 行测#66"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两点之间的线段长度不大于经第三点连接这两点的两段长度之和。当第三点在线段上时，两者相等。","review":{"definition":"两点之间的线段长度不大于经第三点连接这两点的两段长度之和。当第三点在线段上时，两者相等。","explanation":"把工作站视为道路上的点，将甲联络站沿道路所在直线反射。道路上任一点到甲站和到其对称点的距离相等。甲站的对称点和乙站分居道路两侧，所以把工作站建在两点连线与道路的交点，两段距离之和就等于两点间的直线距离。两点沿道路方向相差10千米，垂直道路方向相差24千米，由勾股定理得最短距离为26千米。","references":[],"evidence":"根据两点之间线段最短，可知将工作站建在O点时，距离甲、乙联络站的距离之和最小","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 行测#66":{"paper":"国考 2024 行政执法 行测","n":66,"mod":"数量关系","src":["dfddc59dc6e7d9da5d71.pdf",12],"asrc":["6493f3a6a55c38431852.pdf",20],"card":"e734819e5c214a3dce6257c6","links":[{"id":"k-6d966e1bff9e9de9","role":"解题依据","why":"反射后，两段距离之和在两段共线时达到最小。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-6d966e1bff9e9de9":[["国考 2024 行政执法 行测#66"]]}};
